SELECT pl.source_id, pd.sku_id, pd.sku_no, pd.platform_sku_no as fnSku, SUM(pd.qty) as qty, SUM(pd.picked_qty) as pickedQty FROM picking_lists pl LEFT JOIN picking_detail pd ON pl.id = pd.main_id AND pd.is_deleted = FALSE where pl.is_deleted = false and pd.sku_id is not null and pl.source_id in
#{id}
GROUP BY pl.source_id, pd.sku_id, pd.sku_no, pd.platform_sku_no

SELECT fmd.id as sourceId, rad.sku_id, rad.sku_no, rad.platform_fn_sku as fnSku, SUM(rad.picking_qty) as qty FROM first_mile_delivery fmd LEFT JOIN requisition_application_detail rad ON fmd.source_id = rad.main_id AND rad.is_deleted = FALSE where fmd.is_deleted = false and rad.sku_id is not null and fmd.id in
#{id}
GROUP BY fmd.id, rad.sku_id, rad.sku_no, rad.platform_fn_sku
